/// <summary>
/// CB627_TMSEngineProcessingTOCreation
/// Class to proceede with the creation process for TMS engine
/// </summary>
internal final class METTMSEngineTransferOrderProccess_Pickinglist extends METTMSEngineTransferOrderProccess
{    
}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_transferTable">InventTransferTable record</param>
public void new(InventTransferTable _transferTable, WMSPickingRouteID _pickingRouteId)
{
    this.init(_transferTable);

    pickingRouteId = _pickingRouteId;
}

/// <summary>
/// Create an instance of <c>METTMSEngineTOLinesTmpBuilder</c>
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineTransferOrderProcess enum</param>
/// <param name = "_transferTable"><c>InventTransferTable</c> record</param>
/// <returns>New instance of <c>METTMSEngineTOLinesTmpBuilder</c></returns>
METTMSEngineTOLinesTmpBuilder getTmpBuilderInstance(METTMSEngineTransferOrderProcess _tmsEngineProcess, InventTransferTable _transferTable)
{
    return METTMSEngineTOLinesTmpBuilder::construct(_tmsEngineProcess, _transferTable, '', pickingRouteId);
}

/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    return strFmt("@MET:TMSEngineTransferOrderProcessCreation", transferTable.TransferId);
}
